use std::collections::VecDeque;

struct ConnectionPool {
    // Holding connections in a FIFO Queue
    available: VecDeque<std::net::TcpStream>,
}

impl ConnectionPool {
    fn checkout(&mut self) -> std::net::TcpStream {
        self.available.pop_front().unwrap() // Pops oldest to ensure periodic usage
